Y='#f5c400'
def kpi(items):
    return '<div class="kpis">'+''.join(f'<div><b>{v}</b><span>{l}</span></div>' for v,l in items)+'</div>'
def rows(r):
    return '<table class="spec">'+''.join(f'<tr><td>{a}</td><td>{b}</td></tr>' for a,b in r)+'</table>'
def blk(t,body):
    if isinstance(body,list): body='<ul>'+''.join(f'<li>{x}</li>' for x in body)+'</ul>'
    else: body=f'<p>{body}</p>'
    return f'<div class="blk"><h4>{t}</h4>{body}</div>'
page_no=[0]
def page(title,sub,img,kp,body,tag='ТЕХНИЧЕСКАЯ СПЕЦИФИКАЦИЯ',cover=False):
    page_no[0]+=1
    return f'''<section class="page"><header><div class="hd"><div class="tag">{tag}</div><h1>{title}</h1><p>{sub}</p></div>{f'<img src="{img}">' if img else ''}</header>
{kpi(kp) if kp else ''}<main>{body}</main><footer><span>Каталог оборудования для выгрузки и очистки сыпучих грузов</span><span>{page_no[0]}</span></footer></section>'''
def cols(a,b): return f'<div class="two">{a}{b}</div>'
def cmp_table(head,rs):
    h='<tr>'+''.join(f'<th>{x}</th>' for x in head)+'</tr>'
    return '<table class="cmp">'+h+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in r)+'</tr>' for r in rs)+'</table>'

